        guard log.topics.count == 2 else { throw WrapperError.eventMismatch }
        guard log.topics.first == event.topic else { throw WrapperError.eventMismatch }
        guard let decoded = ABIDecoder.decode(types: event.inputs.filter { !$0.indexed }.map { $0.type }, data: log.data) else { throw WrapperError.invalidValue("Withdrawn(address,uint256)") }
        let topic0 = log.topics[1]
        guard topic0.count == 32 else { throw WrapperError.invalidValue("event topic 0") }
        guard let raw0 = ABIDecoder.decode(types: [event.inputs[0].type], data: topic0)?.first else { throw WrapperError.invalidValue("event field 0") }
        let value0 = try _cast(raw0, as: EthereumAddress.self)
        let value1 = try _cast(decoded[0], as: BigUInt.self)
        return WithdrawnEvent(account: value0, amount: value1)
    }

    /// A decoded custom ABI error.
    public enum DecodedCustomError {
        /// `AlreadySettled()`.
        case alreadySettled(AlreadySettledError)
        /// `IncorrectReservationValue(uint256,uint256)`.
        case incorrectReservationValue(IncorrectReservationValueError)
        /// `NativeTransferFailed()`.
        case nativeTransferFailed(NativeTransferFailedError)
        /// `NoReservation()`.
        case noReservation(NoReservationError)
        /// `NotExpired()`.
        case notExpired(NotExpiredError)
        /// `NothingToWithdraw()`.
        case nothingToWithdraw(NothingToWithdrawError)
        /// `ReservationExists()`.
        case reservationExists(ReservationExistsError)
        /// `Unauthorized()`.
        case unauthorized(UnauthorizedError)
        /// `ZeroAddress()`.
        case zeroAddress(ZeroAddressError)
    }

    /// Decodes a custom revert payload, or returns nil for an unknown selector.
    public static func decodeCustomError(_ data: Data) throws -> DecodedCustomError? {
        guard data.count >= 4 else { throw WrapperError.invalidValue("error selector") }
        let contract = try _contract()
        let selector = Data(data.prefix(4))
        if selector == Data([0x56, 0x0f, 0xf9, 0x00]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "AlreadySettled()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("AlreadySettled()") }
            return .alreadySettled(AlreadySettledError())
        }
        if selector == Data([0xc3, 0x7b, 0xdb, 0xcd]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "IncorrectReservationValue(uint256,uint256)" }), let values = error.decodeEthError(Data(data.dropFirst(4))) else { throw WrapperError.invalidValue("IncorrectReservationValue(uint256,uint256)") }
            guard let raw0 = values["0"] else { throw WrapperError.invalidValue("error field 0") }
            let value0 = try _cast(raw0, as: BigUInt.self)
            guard let raw1 = values["1"] else { throw WrapperError.invalidValue("error field 1") }
            let value1 = try _cast(raw1, as: BigUInt.self)
            return .incorrectReservationValue(IncorrectReservationValueError(expected: value0, actual: value1))
        }
        if selector == Data([0xf4, 0xb3, 0xb1, 0xbc]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "NativeTransferFailed()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("NativeTransferFailed()") }
            return .nativeTransferFailed(NativeTransferFailedError())
        }
        if selector == Data([0x2f, 0x04, 0x1f, 0xe0]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "NoReservation()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("NoReservation()") }
            return .noReservation(NoReservationError())
        }
        if selector == Data([0xd0, 0x40, 0x4f, 0x85]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "NotExpired()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("NotExpired()") }
            return .notExpired(NotExpiredError())
        }
        if selector == Data([0xd0, 0xd0, 0x4f, 0x60]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "NothingToWithdraw()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("NothingToWithdraw()") }
            return .nothingToWithdraw(NothingToWithdrawError())
        }
        if selector == Data([0x73, 0xf1, 0x8a, 0xd7]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "ReservationExists()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("ReservationExists()") }
            return .reservationExists(ReservationExistsError())
        }
        if selector == Data([0x82, 0xb4, 0x29, 0x00]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "Unauthorized()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("Unauthorized()") }
            return .unauthorized(UnauthorizedError())
        }
        if selector == Data([0xd9, 0x2e, 0x23, 0x3d]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "ZeroAddress()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("ZeroAddress()") }
            return .zeroAddress(ZeroAddressError())
        }
        return nil
    }
